export default {
  async main(env, ctx) {
    const { params, upstream, files, urls } = ctx;

    const parseResult = upstream.parse_and_clean?.data;
    const items = parseResult?.outputs?.items || [];
    const previousMeta = parseResult?.outputs?.meta || {};

    const meta = {
      ...previousMeta,
      deduplicationStats: {
        before: items.length,
        after: 0,
        removed: 0,
        duplicateLinks: [],
        duplicateTitles: [],
        timestamp: new Date().toISOString()
      }
    };

    if (items.length === 0) {
      meta.deduplicationStats.after = 0;
      return {
        outputs: {
          items: [],
          meta
        }
      };
    }

    try {
      const seenLinks = new Set();
      const seenTitles = new Set();
      const uniqueItems = [];

      // 按日期排序（最新的优先），这样保留最新的重复项
      const sortedItems = [...items].sort((a, b) => {
        const dateA = a.pubDate ? new Date(a.pubDate).getTime() : 0;
        const dateB = b.pubDate ? new Date(b.pubDate).getTime() : 0;
        return dateB - dateA; // 降序，最新的在前
      });

      for (const item of sortedItems) {
        let isDuplicate = false;

        // 首先检查链接重复
        if (item.link) {
          const normalizedLink = item.link.toLowerCase().trim();
          if (seenLinks.has(normalizedLink)) {
            isDuplicate = true;
            meta.deduplicationStats.duplicateLinks.push({
              link: item.link,
              title: item.title
            });
          } else {
            seenLinks.add(normalizedLink);
          }
        }

        // 如果没有链接或链接不重复，检查标题重复
        if (!isDuplicate && item.title) {
          const normalizedTitle = item.title.toLowerCase().trim();
          if (normalizedTitle && seenTitles.has(normalizedTitle)) {
            // 标题相同但链接不同，可能不是真正的重复
            // 这里可以选择性处理，暂时只记录
            meta.deduplicationStats.duplicateTitles.push({
              title: item.title,
              link: item.link
            });
            // 不标记为重复，因为可能是不同来源的相同新闻
          } else if (normalizedTitle) {
            seenTitles.add(normalizedTitle);
          }
        }

        if (!isDuplicate) {
          uniqueItems.push(item);
        }
      }

      // 恢复原始顺序（如果需要）
      const finalItems = uniqueItems.sort((a, b) => a.index - b.index);

      meta.deduplicationStats.after = finalItems.length;
      meta.deduplicationStats.removed = items.length - finalItems.length;

      // 记录去重策略
      if (meta.deduplicationStats.removed > 0) {
        meta.fallbackStrategies = meta.fallbackStrategies || [];
        meta.fallbackStrategies.push(`移除了${meta.deduplicationStats.removed}个重复条目（基于链接去重）`);
      }

      return {
        outputs: {
          items: finalItems,
          meta
        }
      };

    } catch (error) {
      meta.deduplicationStats.error = error.message;
      // 去重失败时返回原始数据
      return {
        outputs: {
          items,
          meta
        }
      };
    }
  }
}

export default {
  async main(env, ctx) {
    const { params, upstream, files, urls } = ctx;

    const feedUrl = params.feedUrl;
    const timeoutMs = params.timeoutMs || 10000;

    const meta = {
      errors: [],
      warnings: [],
      fallbackStrategies: [],
      timestamp: new Date().toISOString(),
      feedUrl,
      timeoutMs
    };

    if (!feedUrl) {
      meta.errors.push('feedUrl参数缺失');
      return {
        outputs: {
          rawXml: null,
          feedType: null,
          meta
        }
      };
    }

    try {
      // 设置超时
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

      const response = await fetch(feedUrl, {
        signal: controller.signal,
        headers: {
          'User-Agent': 'Mozilla/5.0 (compatible; RSS-Fetcher/1.0)',
          'Accept': 'application/rss+xml, application/atom+xml, application/xml, text/xml'
        }
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        meta.errors.push(`HTTP错误: ${response.status} ${response.statusText}`);
        return {
          outputs: {
            rawXml: null,
            feedType: null,
            meta
          }
        };
      }

      const contentType = response.headers.get('content-type') || '';
      const rawXml = await response.text();

      // 检测feed类型
      let feedType = 'unknown';
      if (contentType.includes('rss') || rawXml.includes('<rss')) {
        feedType = 'rss';
      } else if (contentType.includes('atom') || rawXml.includes('<feed')) {
        feedType = 'atom';
      } else if (contentType.includes('xml') || rawXml.trim().startsWith('<?xml')) {
        feedType = 'xml';
      }

      meta.feedType = feedType;
      meta.contentLength = rawXml.length;
      meta.contentType = contentType;

      if (feedType === 'unknown') {
        meta.warnings.push('无法确定feed类型，尝试作为通用XML解析');
      }

      return {
        outputs: {
          rawXml,
          feedType,
          meta
        }
      };

    } catch (error) {
      meta.errors.push(`抓取失败: ${error.message}`);

      if (error.name === 'AbortError') {
        meta.fallbackStrategies.push('请求超时，考虑使用缓存或重试');
      } else if (error.code === 'ENOTFOUND') {
        meta.fallbackStrategies.push('域名解析失败，检查URL或网络连接');
      } else {
        meta.fallbackStrategies.push('网络错误，尝试备用源或稍后重试');
      }

      return {
        outputs: {
          rawXml: null,
          feedType: null,
          meta
        }
      };
    }
  }
}

export default {
  async main(env, ctx) {
    const { params, upstream, files, urls } = ctx;

    const deduplicateResult = upstream.deduplicate?.data;
    const items = deduplicateResult?.outputs?.items || [];
    const previousMeta = deduplicateResult?.outputs?.meta || {};

    const maxItems = params.maxItems || 10; // 默认10条
    const timeoutMs = params.timeoutMs || 10000;

    const meta = {
      ...previousMeta,
      limitStats: {
        before: items.length,
        maxItems,
        after: 0,
        limited: false,
        timestamp: new Date().toISOString()
      },
      finalOutput: {
        totalItems: 0,
        hasErrors: false,
        hasWarnings: false,
        executionTime: new Date().toISOString()
      }
    };

    // 计算最终输出
    let finalItems = items;

    if (items.length > maxItems) {
      finalItems = items.slice(0, maxItems);
      meta.limitStats.after = maxItems;
      meta.limitStats.limited = true;

      // 记录降级策略
      meta.fallbackStrategies = meta.fallbackStrategies || [];
      meta.fallbackStrategies.push(`输出限制为${maxItems}条（原始${items.length}条）`);
    } else {
      meta.limitStats.after = items.length;
    }

    // 检查是否有错误
    const hasErrors = meta.errors && meta.errors.length > 0;
    const hasWarnings = (meta.warnings && meta.warnings.length > 0) || 
                       (meta.parsingErrors && meta.parsingErrors.length > 0) ||
                       (meta.parsingWarnings && meta.parsingWarnings.length > 0);

    meta.finalOutput.totalItems = finalItems.length;
    meta.finalOutput.hasErrors = hasErrors;
    meta.finalOutput.hasWarnings = hasWarnings;

    // 如果没有数据但有错误，添加降级策略
    if (finalItems.length === 0 && hasErrors) {
      meta.fallbackStrategies = meta.fallbackStrategies || [];
      meta.fallbackStrategies.push('抓取失败，返回空结果集');
    }

    // 如果没有数据但没有明显错误，添加建议
    if (finalItems.length === 0 && !hasErrors) {
      meta.fallbackStrategies = meta.fallbackStrategies || [];
      meta.fallbackStrategies.push('未找到有效条目，检查feed格式或URL');
    }

    // 准备最终输出格式
    const output = {
      success: finalItems.length > 0 && !hasErrors,
      items: finalItems.map(item => ({
        id: item.id,
        title: item.title,
        link: item.link,
        pubDate: item.pubDate,
        source: item.source,
        feedType: item.feedType
      })),
      feedInfo: previousMeta.feedInfo || {},
      meta: {
        stats: {
          totalItems: items.length,
          limited: meta.limitStats.limited,
          maxItems,
          duplicatesRemoved: meta.deduplicationStats?.removed || 0
        },
        errors: meta.errors || [],
        warnings: [
          ...(meta.warnings || []),
          ...(meta.parsingErrors || []),
          ...(meta.parsingWarnings || [])
        ],
        fallbackStrategies: meta.fallbackStrategies || [],
        executionInfo: {
          feedUrl: params.feedUrl,
          feedType: meta.feedType,
          timeoutMs,
          timestamp: new Date().toISOString()
        }
      }
    };

    return {
      outputs: output
    };
  }
}

export default {
  async main(env, ctx) {
    const { params, upstream, files, urls } = ctx;

    const fetchResult = upstream.fetch_feed?.data;
    const rawXml = fetchResult?.outputs?.rawXml;
    const feedType = fetchResult?.outputs?.feedType;
    const previousMeta = fetchResult?.outputs?.meta || {};

    const meta = {
      ...previousMeta,
      parsingErrors: [],
      parsingWarnings: [],
      parsingTimestamp: new Date().toISOString()
    };

    if (!rawXml) {
      meta.parsingErrors.push('没有可解析的XML数据');
      return {
        outputs: {
          items: [],
          feedInfo: {},
          meta
        }
      };
    }

    try {
      // 简单的XML解析（实际使用中可能需要更复杂的解析库）
      const items = [];
      const feedInfo = {};

      // 提取feed基本信息
      const titleMatch = rawXml.match(/<title[^>]*>([^<]+)<\/title>/i);
      if (titleMatch) {
        feedInfo.title = titleMatch[1].trim();
      }

      const linkMatch = rawXml.match(/<link[^>]*>([^<]+)<\/link>/i) || 
                       rawXml.match(/<link[^>]*href="([^"]+)"[^>]*\/?>/i);
      if (linkMatch) {
        feedInfo.link = linkMatch[1].trim();
      }

      // 解析条目
      let itemMatches = [];

      if (feedType === 'rss' || feedType === 'xml') {
        // RSS格式：<item>标签
        const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
        itemMatches = [...rawXml.matchAll(itemRegex)];
      } else if (feedType === 'atom') {
        // Atom格式：<entry>标签
        const entryRegex = /<entry[^>]*>([\s\S]*?)<\/entry>/gi;
        itemMatches = [...rawXml.matchAll(entryRegex)];
      } else {
        // 未知格式，尝试两种模式
        const rssItems = [...rawXml.matchAll(/<item[^>]*>([\s\S]*?)<\/item>/gi)];
        const atomEntries = [...rawXml.matchAll(/<entry[^>]*>([\s\S]*?)<\/entry>/gi)];
        itemMatches = rssItems.length > 0 ? rssItems : atomEntries;

        if (itemMatches.length === 0) {
          meta.parsingWarnings.push('未找到标准的item或entry标签，尝试其他模式');
          // 尝试查找任何包含标题和链接的内容块
          const anyContentRegex = /<(?:item|entry|div|article)[^>]*>([\s\S]*?<\/?(?:title|link)[^>]*>[\s\S]*?)<\/(?:item|entry|div|article)>/gi;
          itemMatches = [...rawXml.matchAll(anyContentRegex)];
        }
      }

      meta.totalItemsFound = itemMatches.length;

      for (let i = 0; i < itemMatches.length; i++) {
        try {
          const itemContent = itemMatches[i][1];

          // 提取标题
          let title = '';
          const titleMatch = itemContent.match(/<title[^>]*>([^<]+)<\/title>/i);
          if (titleMatch) {
            title = titleMatch[1].trim();
          }

          // 提取链接（RSS: <link>，Atom: <link href="...">）
          let link = '';
          const linkMatch = itemContent.match(/<link[^>]*>([^<]+)<\/link>/i) || 
                           itemContent.match(/<link[^>]*href="([^"]+)"[^>]*\/?>/i);
          if (linkMatch) {
            link = linkMatch[1].trim();
          }

          // 提取发布时间
          let pubDate = '';
          const dateMatch = itemContent.match(/<(?:pubDate|published|updated|dc:date)[^>]*>([^<]+)<\/(?:pubDate|published|updated|dc:date)>/i);
          if (dateMatch) {
            pubDate = dateMatch[1].trim();
          }

          // 提取来源/作者
          let source = '';
          const sourceMatch = itemContent.match(/<(?:author|dc:creator|source)[^>]*>([^<]+)<\/(?:author|dc:creator|source)>/i) ||
                             itemContent.match(/<(?:author|dc:creator|source)[^>]*name="([^"]+)"[^>]*\/?>/i);
          if (sourceMatch) {
            source = sourceMatch[1].trim();
          }

          // 清理数据
          if (title) {
            // 移除HTML标签和多余空格
            title = title.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
          }

          if (link) {
            // 确保链接是完整的URL
            try {
              if (!link.startsWith('http')) {
                const baseUrl = feedInfo.link || params.feedUrl;
                if (baseUrl) {
                  const urlObj = new URL(baseUrl);
                  link = new URL(link, urlObj.origin + urlObj.pathname).href;
                }
              }
            } catch (e) {
              meta.parsingWarnings.push(`链接处理失败: ${link}`);
            }
          }

          // 标准化日期格式
          let normalizedDate = '';
          if (pubDate) {
            try {
              const date = new Date(pubDate);
              if (!isNaN(date.getTime())) {
                normalizedDate = date.toISOString();
              }
            } catch (e) {
              // 保持原始日期字符串
              normalizedDate = pubDate;
            }
          }

          // 生成唯一ID（基于链接或标题）
          const id = link || `item-${i}-${Date.now()}`;

          items.push({
            id,
            title,
            link,
            pubDate: normalizedDate || pubDate,
            source,
            rawDate: pubDate,
            index: i,
            feedType
          });

        } catch (itemError) {
          meta.parsingWarnings.push(`条目${i}解析失败: ${itemError.message}`);
        }
      }

      meta.successfullyParsed = items.length;

      if (items.length === 0 && itemMatches.length > 0) {
        meta.parsingErrors.push('找到条目标签但未能提取有效数据');
      }

      return {
        outputs: {
          items,
          feedInfo,
          meta
        }
      };

    } catch (error) {
      meta.parsingErrors.push(`解析失败: ${error.message}`);
      return {
        outputs: {
          items: [],
          feedInfo: {},
          meta
        }
      };
    }
  }
}

export default {
  async main(env, ctx) {
    const { upstream } = ctx;

    const prev = upstream.limit_output?.data;
    const outputs = prev?.outputs ?? null;

    const meta = {
      errors: [],
      warnings: [],
      builtAt: new Date().toISOString(),
      wroteFile: false,
      fileName: "rss-output.json",
      filePath: null,
    };

    const json = JSON.stringify(outputs, null, 2);

    try {
      const r = await ctx.artifacts.writeText(meta.fileName, json, { kind: "file", summary: "RSS 工作流输出 JSON" });
      meta.wroteFile = true;
      meta.filePath = r?.absPath || null;
    } catch (e) {
      meta.errors.push(`写入/注册产物失败: ${e instanceof Error ? e.message : String(e)}`);
    }

    return {
      outputs: {
        json,
        file_name: meta.fileName,
        file_path: meta.filePath,
        wrote_file: meta.wroteFile,
        meta,
      },
    };
  },
};
